// Writes migrations/0005_customise.sql: the "Leave out" and Cajun fries choices
// for dishes that are already in the live database. Dishes are matched by name,
// so the ids in the live database do not matter.
import { writeFileSync } from 'node:fs';
import { menu } from '../menu/menu.mjs';

const q = (v) => `'${String(v).replace(/'/g, "''")}'`;
const out = [
  '-- Generated by scripts/build-customise.mjs.',
  '-- Lets customers leave ingredients off a dish and upgrade to Cajun fries on dishes served on fries.',
];

for (const item of menu.flatMap((c) => c.items)) {
  (item.groups || []).forEach((group, index) => {
    if (!group.added) return;
    out.push(
      `INSERT INTO option_groups (item_id, name, min_choices, max_choices, sort) SELECT id, ${q(group.name)}, ${group.min}, ${group.max}, ${index + 10} FROM items WHERE name = ${q(item.name)};`
    );
    group.choices.forEach((choice, sort) => {
      out.push(
        `INSERT INTO options (group_id, name, price_cents, alcohol, available, sort) SELECT g.id, ${q(choice.name)}, ${Math.round((choice.price || 0) * 100)}, 0, 1, ${sort} FROM option_groups g JOIN items i ON i.id = g.item_id WHERE i.name = ${q(item.name)} AND g.name = ${q(group.name)};`
      );
    });
  });
}

writeFileSync(new URL('../migrations/0005_customise.sql', import.meta.url), out.join('\n') + '\n');
console.log(`0005_customise.sql written: ${out.length - 2} statements`);
